package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class AccountingState(val loading:Boolean=false,val mode:String="ledgers",val data:JsonObject=buildJsonObject{},val editing:Boolean=false,val error:String?=null)
class AccountAccountingViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(AccountingState());val state:StateFlow<AccountingState> = _state;init{load()};fun show(m:String){_state.value=_state.value.copy(mode=m);load()};fun load()=viewModelScope.launch{try{_state.value=_state.value.copy(loading=true,error=null);_state.value=_state.value.copy(loading=false,data=api.accountingOverview())}catch(e:Exception){_state.value=_state.value.copy(loading=false,error=if(e is IOException)"Offline" else "Accounting data rejected by server")}};fun edit(v:Boolean=true){_state.value=_state.value.copy(editing=v)};fun save(p:JsonObject)=viewModelScope.launch{try{api.accountingAction(_state.value.mode,p);edit(false);load()}catch(e:Exception){_state.value=_state.value.copy(error="Authoritative accounting validation rejected this action.")}}}
